#!/bin/bash
# ============================================================================
# case_sheet_glasses_info_and_registration_validation.sh
#
# Three changes:
#
# 1. OPD Case Sheet printout -- "Type of Glass" and "Remarks (if any)"
#    now print under the Refraction section. These map to
#    optometry_assessments.glasses_type / glasses_remarks -- columns that
#    already existed in the database but had no UI to enter them and
#    weren't on the printout. Added a "Type of Glass" (free text with
#    suggestions: Single Vision Distance/Near, Bifocal, Progressive,
#    Photochromatic, Anti-Reflective Coated, Blue Cut) and "Remarks"
#    field to the optometrist's Refraction section, wired them into
#    saves, and added them to the case sheet's default print template
#    (only shows when either field has a value).
#
#    DATABASE: No migration needed -- glasses_type/glasses_remarks
#    columns already exist on both Supabase projects.
#
# 2. Patient Registration -- Last Name is no longer required. First
#    Name, Gender, and Mobile remain required. (No database change
#    needed -- last_name is NOT NULL at the DB level but an empty
#    string satisfies that fine, and the registration RPC already
#    handles it that way.)
#
# 3. Patient Registration -- Age is now required, marked with an
#    asterisk (*), same as the other mandatory fields.
#
#   MODIFIED: app/(main)/optometry/[id]/optometry-workspace.js
#   MODIFIED: app/(main)/optometry/actions.js
#   MODIFIED: app/print-templates/actions.js
#   MODIFIED: app/(main)/patients/new/registration-form.js
#
# Run this from the root of your veda-hmis repo in GitHub Codespaces.
# ============================================================================

set -e

echo "==> Case sheet Type of Glass/Remarks + registration validation updates"
echo ""

if [ ! -f "package.json" ] || [ ! -d "app" ]; then
  echo "ERROR: This doesn't look like the veda-hmis repo root (no package.json / app dir found)."
  echo "cd into your repo root and re-run this script."
  exit 1
fi

echo "==> Overwriting app/(main)/optometry/[id]/optometry-workspace.js"
echo "" | base64 -d > "app/(main)/optometry/[id]/optometry-workspace.js"

echo "==> Overwriting app/(main)/optometry/actions.js"
echo "" | base64 -d > "app/(main)/optometry/actions.js"

echo "==> Overwriting app/print-templates/actions.js"
echo "" | base64 -d > "app/print-templates/actions.js"

echo "==> Overwriting app/(main)/patients/new/registration-form.js"
echo "" | base64 -d > "app/(main)/patients/new/registration-form.js"

echo ""
echo "==> Files written. Verifying build..."
if command -v npm >/dev/null 2>&1; then
  npm run build || { echo "BUILD FAILED -- check output above before pushing."; exit 1; }
else
  echo "npm not found -- skipping build verification, run 'npm run build' manually."
fi

echo ""
echo "==> Done. Review changes with: git status && git diff"
echo "==> To deploy, run:"
echo "    git add -A"
echo '    git commit -m "Case sheet: add Type of Glass/Remarks under Refraction; Registration: drop last-name requirement, require age"'
echo "    git push"
